 let mapMotion=null,categoryAnimation=null;
 let routeWorker=null,routeWorkerReady=false,routeWorkerVersion=0,routeWorkerRequest=0,routeWorkerPending=new Map();
 function cloneForWorker(value){return typeof structuredClone==='function'?structuredClone(value):JSON.parse(JSON.stringify(value));}
 function initRouteWorker(){
  if(!window.Worker)return;
  try{
   routeWorker=new Worker('../shared/route-worker.js');
   routeWorker.onmessage=e=>{const m=e.data||{};if(m.type==='ready'){routeWorkerReady=true;routeWorkerVersion=m.version;const idle=window.requestIdleCallback||((fn)=>setTimeout(fn,80));idle(()=>{if(routeWorkerReady)routeWorker.postMessage({type:'warm',version:routeWorkerVersion,options:{origins:4,targets:24}});});return;}if(m.type==='warmed')return;const pending=routeWorkerPending.get(m.requestId);if(!pending)return;routeWorkerPending.delete(m.requestId);if(m.type==='route')pending.resolve(m.result);else pending.reject(Error(m.error||'后台路线计算失败'))};
   routeWorker.onerror=()=>{routeWorkerReady=false;for(const pending of routeWorkerPending.values())pending.reject(Error('后台路线计算不可用'));routeWorkerPending.clear();};
  }catch{routeWorker=null;routeWorkerReady=false;}
 }
 function syncRouteWorker(){
  if(!routeWorker)return;routeWorkerReady=false;routeWorkerVersion=Number(dataset.meta.routeVersion||0);
  try{routeWorker.postMessage({type:'init',version:routeWorkerVersion,dataset:cloneForWorker(dataset)});}catch{routeWorkerReady=false;}
 }
 function workerRoute(fromId,toId,routeMode){
  if(!routeWorker)return Promise.reject(Error('后台路线计算不可用'));
  return new Promise((resolve,reject)=>{
   const started=performance.now(),wait=()=>{
    if(routeWorkerReady&&routeWorkerVersion===Number(dataset.meta.routeVersion||0)){
     const requestId=++routeWorkerRequest,timer=setTimeout(()=>{routeWorkerPending.delete(requestId);reject(Error('后台路线计算超时'));},5000);
     routeWorkerPending.set(requestId,{resolve:value=>{clearTimeout(timer);resolve(value)},reject:error=>{clearTimeout(timer);reject(error)}});
     try{routeWorker.postMessage({type:'route',requestId,version:routeWorkerVersion,fromId,toId,mode:routeMode});}catch(error){routeWorkerPending.delete(requestId);clearTimeout(timer);reject(error);}return;
    }
    if(performance.now()-started>=5000){reject(Error('后台路线数据尚未就绪'));return;}
    setTimeout(wait,16);
   };wait();
  });
 }
 const icons={'学习':'▤','服务':'⌘','生活':'☕','运动':'◈','实验':'⚗','出入口':'↗','其他':'◇'};
 let firstRouteNoticeShown=false,routeProgressTimer=null;
 function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.add('hidden'),4200);}
 const GEOREF={baoshan:{lat:31.364339,lon:121.435249,scaleX:.0000105,scaleY:.0000082},yangpu:{lat:31.3012,lon:121.5006,scaleX:.0000062,scaleY:.0000052}};
 const mapToGeo=(campus,x,y)=>{const g=GEOREF[campus]||GEOREF.baoshan,cy=(mapSize(campus).height/2);return {latitude:g.lat-(y-cy)*g.scaleY,longitude:g.lon+(x-500)*g.scaleX};};
 const geoToMap=(campus,lat,lon)=>{const g=GEOREF[campus]||GEOREF.baoshan,cy=(mapSize(campus).height/2);return {x:500+(lon-g.lon)/g.scaleX,y:cy-(lat-g.lat)/g.scaleY};};
 function areaFor(cid,source=dataset){return source?.meta?.mapAnnotations?.[cid]?.unexploredAreas||[];}
 function pointInPolygon(x,y,points){let inside=false;for(let i=0,j=points.length-1;i<points.length;j=i++){const [xi,yi]=points[i],[xj,yj]=points[j],hit=((yi>y)!==(yj>y))&&x<(xj-xi)*(y-yi)/(yj-yi||1e-9)+xi;if(hit)inside=!inside;}return inside;}
 function isUnexploredPoint(cid,x,y,source=dataset){return areaFor(cid,source).some(area=>pointInPolygon(Number(x),Number(y),area.points||[]));}
 const markerPoint=place=>({x:Number.isFinite(place.markerX)?place.markerX:place.mapX,y:Number.isFinite(place.markerY)?place.markerY:place.mapY});
 function isUnexploredPlace(place){if(!place?.campusId)return false;const p=markerPoint(place);return Number.isFinite(p.x)&&areaFor(place.campusId).some(area=>pointInPolygon(p.x,p.y,area.displayPoints||area.points||[]));}
 function orientation(a,b,c){return (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);}
 function blockedCrossing(a,b,c,d){const eps=1e-6,o1=orientation(a,b,c),o2=orientation(a,b,d),o3=orientation(c,d,a),o4=orientation(c,d,b);if(Math.abs(o1)<eps||Math.abs(o2)<eps||Math.abs(o3)<eps||Math.abs(o4)<eps)return false;return (o1>0)!==(o2>0)&&(o3>0)!==(o4>0);}
 function crossesBarrier(a,b,paths){return (paths||[]).some(path=>{const points=path.points||[];for(let i=1;i<points.length;i++){const c={x:Number(points[i-1][0]),y:Number(points[i-1][1])},d={x:Number(points[i][0]),y:Number(points[i][1])};if(blockedCrossing(a,b,c,d))return true;}return false;});}
 function addEdge(d,from,to,kind='path',accessible=true,source='connector'){if(!from||!to||from===to)return;const id=[from,to].sort().join('~');if(d.edges.some(e=>e.id===id))return;const a=d.nodes.find(n=>n.id===from),b=d.nodes.find(n=>n.id===to);if(!a||!b)return;const length=Math.max(6,Math.round(Math.hypot(a.x-b.x,a.y-b.y)*1.7));d.edges.push({id,from,to,lengthMeters:length,timeSeconds:Math.max(5,Math.round(length/(kind==='stairs'?0.8:1.25))),accessible,kind,source});}
 function augment(d){
  if(d.meta?.schoolId==='sh-jiguang'){
   // Coordinate upgrades rebuild generated nodes, keeping imported indoor nodes intact.
   d.nodes=d.nodes.filter(n=>!String(n.id).startsWith('geo-')&&!String(n.id).startsWith('waypoint-'));
   const existing=new Set(d.places.map(p=>p.id)),source=window.CampusMapPlaces||[];
   for(const base of source){if(existing.has(base.id))continue;const p=structuredClone(base),nodeId='geo-'+p.id,geo=mapToGeo(p.campusId,p.mapX,p.mapY);p.nodeId=nodeId;p.latitude=geo.latitude;p.longitude=geo.longitude;d.places.push(p);d.nodes.push({id:nodeId,name:p.name,mapId:'outdoor',x:p.mapX,y:p.mapY,latitude:geo.latitude,longitude:geo.longitude,campusId:p.campusId});}
   // Bundled map records may already exist in campus.json; bind every coordinate record to its map node.
   for(const p of d.places){if(!d.meta.schoolId||!Number.isFinite(p.mapX)||!Number.isFinite(p.mapY)||!p.campusId)continue;const nodeId=p.nodeId||'geo-'+p.id;p.nodeId=nodeId;const geo=mapToGeo(p.campusId,p.mapX,p.mapY);p.latitude=geo.latitude;p.longitude=geo.longitude;if(!d.nodes.some(n=>n.id===nodeId))d.nodes.push({id:nodeId,name:p.name,mapId:'outdoor',x:p.mapX,y:p.mapY,latitude:p.latitude,longitude:p.longitude,campusId:p.campusId});}
   // Rebuild only the generated campus graph. This removes the previous nearest-neighbour approximation.
   d.edges=d.edges.filter(e=>!(String(e.from).startsWith('geo-')||String(e.to).startsWith('geo-')||String(e.from).startsWith('waypoint-')||String(e.to).startsWith('waypoint-')));
   const annotations=d.meta.mapAnnotations||{}, upperPlaces=new Set(['photo-bs-activity','photo-bs-meeting','photo-bs-tiered']);
   for(const [cid,ann] of Object.entries(annotations)){
    const waypoint=new Map(),ground=[],upper=[];
    const addPoint=(key,pt,level)=>{const id='waypoint-'+cid+'-'+key.replace(/[^\w-]/g,'-'),old=waypoint.get(key);if(old)return old;if(!d.nodes.some(n=>n.id===id))d.nodes.push({id,name:level===2?'二层通道':'校园通道',mapId:'outdoor',x:Number(pt[0]),y:Number(pt[1]),campusId:cid,level});waypoint.set(key,id);(level===2?upper:ground).push(id);return id;};
    for(const path of ann.groundPaths||[]){let prev=null;for(let i=0;i<path.points.length;i++){const id=addPoint(path.id+'-'+i,path.points[i],1);if(prev)addEdge(d,prev,id,'path',true,'annotated');prev=id;}}
    for(const path of ann.upperPaths||[]){let prev=null;for(let i=0;i<path.points.length;i++){const id=addPoint(path.id+'-'+i,path.points[i],2);if(prev)addEdge(d,prev,id,'upper',false,'annotated');prev=id;}}
    for(const stair of ann.stairs||[]){const a=addPoint(stair.id+'-upper',stair.upper,2),b=addPoint(stair.id+'-ground',stair.ground,1);addEdge(d,a,b,'stairs',false,'annotated');}
    // Join marked crossings within each floor; orange/blue intersections remain separate floors.
    for(const list of [ground,upper]){const pts=list.map(id=>d.nodes.find(n=>n.id===id)).filter(Boolean);for(const a of pts){for(const b of pts.filter(x=>x!==a).sort((u,v)=>Math.hypot(u.x-a.x,u.y-a.y)-Math.hypot(v.x-a.x,v.y-a.y)).slice(0,2))if(Math.hypot(a.x-b.x,a.y-b.y)<=105)addEdge(d,a.id,b.id,list===ground?'path':'upper',list===ground);}}
    for(const stair of ann.stairs||[]){const a=d.nodes.find(n=>n.id==='waypoint-'+cid+'-'+stair.id+'-upper'),b=d.nodes.find(n=>n.id==='waypoint-'+cid+'-'+stair.id+'-ground');if(!a||!b)continue;for(const w of upper.map(id=>d.nodes.find(n=>n.id===id)).filter(Boolean).sort((u,v)=>Math.hypot(u.x-a.x,u.y-a.y)-Math.hypot(v.x-a.x,v.y-a.y)).slice(0,1))if(Math.hypot(w.x-a.x,w.y-a.y)<=105)addEdge(d,a.id,w.id,'upper',false);for(const w of ground.map(id=>d.nodes.find(n=>n.id===id)).filter(Boolean).sort((u,v)=>Math.hypot(u.x-b.x,u.y-b.y)-Math.hypot(v.x-b.x,v.y-b.y)).slice(0,1))if(Math.hypot(w.x-b.x,w.y-b.y)<=105)addEdge(d,b.id,w.id,'path',true);}
    for(const n of d.nodes.filter(n=>n.id.startsWith('geo-')&&n.campusId===cid)){
      const place=d.places.find(p=>p.nodeId===n.id);if(place?.accessRestriction==='event-only'||isUnexploredPoint(cid,n.x,n.y,d))continue;
      const target=upperPlaces.has(place?.id)?upper:ground,choices=target.map(id=>d.nodes.find(x=>x.id===id)).filter(Boolean).sort((a,b)=>Math.hypot(a.x-n.x,a.y-n.y)-Math.hypot(b.x-n.x,b.y-n.y)).slice(0,2);
      for(const w of choices)if(!isUnexploredPoint(cid,w.x,w.y,d))addEdge(d,n.id,w.id,upperPlaces.has(place?.id)?'upper':'path',!upperPlaces.has(place?.id));
    }
    // Red boundaries are barriers. Remove only graph segments that actually cross a barrier;
    // blue/orange paths that merely touch a boundary endpoint remain usable.
    const barriers=ann.blockedPaths||[];
    d.edges=d.edges.filter(e=>{const a=d.nodes.find(n=>n.id===e.from),b=d.nodes.find(n=>n.id===e.to);if(a?.campusId!==cid||b?.campusId!==cid)return true;if(isUnexploredPoint(cid,a.x,a.y,d)||isUnexploredPoint(cid,b.x,b.y,d))return false;if(e.kind==='stairs'||e.source==='annotated')return true;return !crossesBarrier(a,b,barriers);});
   }
   d.meta.georeferencing={crs:'WGS84',method:'QGIS Georeferencer-style affine control points',controlPoints:[{name:'宝山校区中心',latitude:GEOREF.baoshan.lat,longitude:GEOREF.baoshan.lon,mapX:500,mapY:325},{name:'杨浦校区中心',latitude:GEOREF.yangpu.lat,longitude:GEOREF.yangpu.lon,mapX:500,mapY:325}],accuracy:'校区中心已与公开坐标配准；建筑级坐标仍为简化示意，需用更多实测控制点复核。'};
  }
  for(const p of d.places)p.buildingName=d.buildings.find(b=>b.id===p.buildingId)?.name||'';return d;
 }

 try{
  bundled=CampusCore.validate(window.CAMPUS_EMBEDDED_DATA||await (await fetch('../data/campus.json')).json());
  try{dataset=augment(CampusCore.validate(JSON.parse(localStorage.getItem(KEY)||'null')));}catch{dataset=augment(structuredClone(bundled));}
  if(bundled.meta.schoolId&&dataset.meta.schoolId!==bundled.meta.schoolId){const old=dataset;try{localStorage.setItem(KEY+'-before-jiguang',JSON.stringify(old));}catch{}dataset=augment(structuredClone(bundled));for(const p of old.places.filter(p=>p.status!=='demo')){if(dataset.places.some(x=>x.id===p.id))continue;const b=old.buildings.find(b=>b.id===p.buildingId);if(b&&!dataset.buildings.some(x=>x.id===b.id))dataset.buildings.push({...b,x:null,y:null,width:null,height:null});dataset.places.push({...p,nodeId:null});}augment(dataset);}
  if(bundled.meta.schoolId&&dataset.meta.schoolId===bundled.meta.schoolId&&Number(dataset.meta.contentVersion||0)<Number(bundled.meta.contentVersion||0)){for(const base of bundled.places){const p=dataset.places.find(p=>p.id===base.id);if(!p)continue;if(p.status==='official'){p.campusIds=base.campusIds;p.campusScope=base.campusScope;p.category=base.category;}if(Number.isFinite(base.mapX)&&Number.isFinite(base.mapY)){p.mapX=base.mapX;p.mapY=base.mapY;p.coordinateVersion=base.coordinateVersion||bundled.meta.mapCoordinateVersion||1;p.markerX=base.markerX;p.markerY=base.markerY;p.mapSource=base.mapSource;p.wasteKind=base.wasteKind;}}for(const base of bundled.buildings){const b=dataset.buildings.find(b=>b.id===base.id);if(b)b.campusId=base.campusId;}dataset.meta.contentVersion=bundled.meta.contentVersion;dataset.meta.routeVersion=bundled.meta.routeVersion||dataset.meta.routeVersion;dataset.meta.mapCoordinateVersion=bundled.meta.mapCoordinateVersion||dataset.meta.mapCoordinateVersion;dataset.meta.mapAnnotations=structuredClone(bundled.meta.mapAnnotations||{});dataset.meta.mapDataNote=bundled.meta.mapDataNote||dataset.meta.mapDataNote;augment(dataset);}
  for(const base of [...bundled.places,...(window.CampusMapPlaces||[])]){if(!base.descriptionVersion)continue;const place=dataset.places.find(p=>p.id===base.id);if(!place||Number(place.descriptionVersion||0)>=base.descriptionVersion)continue;const purpose=String(place.purpose||'');if(!purpose||purpose.includes('具体服务以校内公告为准')||purpose.includes('学校简介列出的校园设施')){place.purpose=base.purpose;place.intents=[...base.intents];place.aliases=[...(base.aliases||[])];}place.descriptionVersion=base.descriptionVersion;}
  if(dataset.meta.dataStatus==='demo'){const existing=new Set(dataset.places.map(p=>p.id));for(const p of bundled.places)if(p.status==='demo'&&!existing.has(p.id)){dataset.places.push(structuredClone(p));if(p.nodeId&&!dataset.nodes.some(n=>n.id===p.nodeId)){dataset.nodes.push(structuredClone(bundled.nodes.find(n=>n.id===p.nodeId)));dataset.edges.push(...structuredClone(bundled.edges.filter(e=>e.from===p.nodeId||e.to===p.nodeId)));}}augment(dataset);}
  try{favorites=JSON.parse(localStorage.getItem(FAV)||'[]');if(!Array.isArray(favorites))favorites=[];}catch{favorites=[];}
  if(!window.CAMPUS_EMBEDDED_DATA)try{config=await(await fetch('/api/config')).json();}catch{}
 }catch(e){$('panel').innerHTML='<div class="empty"><b>地点数据加载失败</b>'+esc(e.message)+'</div>';return;}
 if(dataset.meta.schoolId){CATEGORIES=['','学习','生活','运动','实验','服务','交通'];campus=['yangpu','baoshan'].includes(localStorage.getItem('campus-current-campus'))?localStorage.getItem('campus-current-campus'):'yangpu';}
 function save(){augment(dataset);dataset.meta.routeVersion=Number(dataset.meta.routeVersion||0)+1;CampusCore.clearRouteCache(dataset);try{localStorage.setItem(KEY,JSON.stringify(dataset));}catch{toast('本机存储空间不足，请导出数据保存。');}syncRouteWorker();updateHeader();updateSelectors();render();renderMap();}
 function updateHeader(){const demos=dataset.places.filter(p=>p.status==='demo').length;$('data-status').textContent=demos?'示例数据':dataset.places.length?(dataset.meta.schoolId?'济光公开资料':'已导入地点'):'真实地点待填';$('notice').textContent=demos?'示例校园 · 名称、位置与路线待替换':dataset.meta.schoolId?'上海济光职业技术学院 · 公开资料 / 学生项目':'已录入 '+dataset.places.length+' 个地点 · 请核实坐标和通行条件';$('data-summary').textContent=`当前 ${dataset.places.length} 个地点 · ${dataset.places.filter(p=>p.nodeId).length} 个已绑定门口节点 · ${dataset.places.filter(p=>!p.nodeId).length} 个待补导航。`;if(!$('categories').dataset.ready){$('categories').innerHTML=CATEGORIES.map(c=>`<button data-category="${c}">${c||'全部'}</button>`).join('');$('categories').dataset.ready='1';}document.querySelectorAll('[data-campus]').forEach(b=>{b.classList.toggle('active',b.dataset.campus===campus);b.setAttribute('aria-pressed',String(b.dataset.campus===campus));});$('campus-switch').classList.toggle('hidden',!campus);document.querySelectorAll('#categories [data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-pressed',String(b.dataset.category===category));if(campus)b.innerHTML=esc(b.dataset.category||'全部')+'<small>'+findPlaces(query,b.dataset.category).length+'</small>';});}
 function campusLabel(p){const ids=CampusCore.campusIds(dataset,p);return ids.length===1?campusName(ids[0])+'校区':p.recordKind==='info'?'全校通用资料':'校区待核实';}
 function positionLabel(p){if(p.recordKind==='campus')return p.address;if(p.recordKind==='program')return [p.buildingName,'2026自主招生校区'].filter(Boolean).join(' · ');if(p.recordKind==='info')return campusLabel(p)+(p.address?' · '+p.address:' · 官方资料 / 服务入口');return [p.buildingName,p.floor!==null&&p.floor!==undefined&&p.floor!==''?p.floor+' 楼':'',p.room?p.room+' 门牌':''].filter(Boolean).join(' · ')||'具体位置待补充';}
 function updateSelectors(){const bid=mapId==='outdoor'?'outdoor':dataset.nodes.find(n=>n.mapId===mapId)?.buildingId||mapId.split(':')[0];$('building-select').innerHTML='<option value="outdoor">校园总览</option>'+dataset.buildings.filter(b=>!campus||CampusCore.campusIds(dataset,{buildingId:b.id}).includes(campus)).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('');$('building-select').value=bid;const b=dataset.buildings.find(b=>b.id===bid);$('floor-select').classList.toggle('hidden',!b||(dataset.meta.schoolId&&!b.floors?.length));if(b){const floors=b.floors?.length?b.floors:[1];$('floor-select').innerHTML=floors.map(f=>`<option value="${esc(f)}">${esc(f)} 楼</option>`).join('');const n=dataset.nodes.find(n=>n.mapId===mapId);$('floor-select').value=String(n?.floor??floors[0]);}}
 function resetMapView(){zoom=1;pan={x:0,y:0};}
