 function renderRoute(){const r=activeRoute,routeResult=$('route-result');if(!r||!routeResult)return;routeResult.innerHTML=`<div class="route-stats"><div><b>${r.distanceMeters}</b><span> 米</span><small>${r.provider==='anyplace'?'Anyplace 路线':'本地地图连通图'}</small></div><div><b>${Math.ceil(r.durationSeconds/60)}</b><span> 分钟</span><small>预计步行时间</small></div></div><p class="route-complete">路线已生成 · 用时 ${((r.thinkingMs||0)/1000).toFixed(1)} 秒</p>`+(r.alternatives?'<div class="route-alternatives">'+r.alternatives.map((a,i)=>`<button class="route-option" data-route-option="${i}"><b>${esc(a.name)}</b><span>${esc(a.advantage||'')+(a.disadvantage?' · '+esc(a.disadvantage):'')}</span><small>点击进入地图</small></button>`).join('')+'</div>':'')+`<button class="route-entry" data-route-open="1">点击进入路线地图 ↗</button>`+r.steps.map((s,i)=>`<button class="step" data-step="${i}"><i>${i+1}</i><span>${esc(s.text)}${s.meters?'<small>'+s.meters+' 米</small>':''}</span></button>`).join('')+`<div class="route-legend"><span class="legend-route">━━</span>普通通行　<span class="legend-stairs">┅</span>楼梯　<span class="legend-lift">┅</span>电梯</div>`;}
