 function routeSegmentMarkup(a,b){const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy);if(!Number.isFinite(len)||len<1)return '';const mx=(a.x+b.x)/2,my=(a.y+b.y)/2,angle=Math.atan2(dy,dx)*180/Math.PI;return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#126a55" stroke-width="3" vector-effect="non-scaling-stroke" stroke-linecap="round" marker-end="url(#nav-arrow)"/><line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#ddeb94" stroke-width="1.5" vector-effect="non-scaling-stroke" stroke-dasharray="4 8"/><path d="M -7 -5 L 7 0 L -7 5 Z" transform="translate(${mx} ${my}) rotate(${angle})" fill="#126a55" stroke="#fff" stroke-width="1" vector-effect="non-scaling-stroke"/>`;}
